using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Markup;
namespace FontFilter;
public sealed class ThemeSettingsWindow:Window
{
 public string SelectedColor{get;private set;}
 public ThemeSettingsWindow(string current){LightTheme.Apply(this);Title="自定义主题颜色";Width=460;Height=530;ResizeMode=ResizeMode.NoResize;WindowStartupLocation=WindowStartupLocation.CenterOwner;SelectedColor=ThemeService.IsValid(current)?current:ThemeService.DefaultColor;
  var panel=new StackPanel{Margin=new Thickness(26)};Content=panel;panel.Children.Add(new TextBlock{Text="让工作台有自己的颜色",FontSize=21,FontWeight=FontWeights.SemiBold});panel.Children.Add(new TextBlock{Text="调整主题强调色，自动搭配文字与背景。",Margin=new Thickness(0,8,0,18),Foreground=Brushes.SlateGray});var preview=new Border{CornerRadius=new CornerRadius(14),Padding=new Thickness(20),Margin=new Thickness(0,0,0,16)};var previewText=new TextBlock{Text="字里行间  /  字体工作台",FontSize=19,FontWeight=FontWeights.SemiBold};preview.Child=previewText;panel.Children.Add(preview);
  var swatches=new WrapPanel{Margin=new Thickness(0,0,0,14)};panel.Children.Add(swatches);var hex=new TextBox{Text=SelectedColor,MaxLength=7,Margin=new Thickness(0,0,0,12)};System.Windows.Automation.AutomationProperties.SetName(hex,"主题十六进制颜色");panel.Children.Add(hex);var warning=new TextBlock{Foreground=Brushes.Firebrick,Margin=new Thickness(0,3,0,10)};
  var channels=new Slider[3];var values=new TextBlock[3];var sliderTemplate=(ControlTemplate)XamlReader.Parse("""
<ControlTemplate xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" TargetType="Slider"><Grid Height="30"><Border Height="9" CornerRadius="4" Background="{TemplateBinding Background}" VerticalAlignment="Center"/><Track x:Name="PART_Track" IsDirectionReversed="{TemplateBinding IsDirectionReversed}"><Track.DecreaseRepeatButton><RepeatButton Command="Slider.DecreaseLarge" Focusable="False"><RepeatButton.Template><ControlTemplate TargetType="RepeatButton"><Border Background="Transparent"/></ControlTemplate></RepeatButton.Template></RepeatButton></Track.DecreaseRepeatButton><Track.Thumb><Thumb Width="20" Height="20" Cursor="Hand"><Thumb.Template><ControlTemplate TargetType="Thumb"><Ellipse Fill="White" Stroke="#27414A" StrokeThickness="2"/></ControlTemplate></Thumb.Template></Thumb></Track.Thumb><Track.IncreaseRepeatButton><RepeatButton Command="Slider.IncreaseLarge" Focusable="False"><RepeatButton.Template><ControlTemplate TargetType="RepeatButton"><Border Background="Transparent"/></ControlTemplate></RepeatButton.Template></RepeatButton></Track.IncreaseRepeatButton></Track></Grid></ControlTemplate>
""");
  for(int i=0;i<3;i++){var row=new DockPanel{Margin=new Thickness(0,0,0,8)};row.Children.Add(new TextBlock{Text=new[]{"H 色相","S 饱和度","B 亮度"}[i],Width=68,VerticalAlignment=VerticalAlignment.Center});values[i]=new TextBlock{Width=46,TextAlignment=TextAlignment.Right,VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(8,0,0,0)};DockPanel.SetDock(values[i],Dock.Right);row.Children.Add(values[i]);channels[i]=new Slider{Minimum=0,Maximum=i==0?360:100,TickFrequency=1,IsSnapToTickEnabled=true,Template=sliderTemplate};System.Windows.Automation.AutomationProperties.SetName(channels[i],new[]{"色相 H","饱和度 S","亮度 B"}[i]);row.Children.Add(channels[i]);panel.Children.Add(row);}panel.Children.Add(warning);
  bool updating=false;
  void RenderColor(Color color){SelectedColor=$"#{color.R:X2}{color.G:X2}{color.B:X2}";warning.Text="";preview.Background=new SolidColorBrush(color);previewText.Foreground=new SolidColorBrush(ThemeService.TextColor(color));for(int i=0;i<3;i++)values[i].Text=channels[i].Value.ToString("F0")+(i==0?"°":"%");var hue=new LinearGradientBrush{StartPoint=new Point(0,0.5),EndPoint=new Point(1,0.5)};foreach(var h in new[]{0,60,120,180,240,300,360})hue.GradientStops.Add(new GradientStop(HsbColor.ToColor(h,100,100),h/360d));channels[0].Background=hue;channels[1].Background=new LinearGradientBrush(HsbColor.ToColor(channels[0].Value,0,channels[2].Value),HsbColor.ToColor(channels[0].Value,100,channels[2].Value),0);channels[2].Background=new LinearGradientBrush(Colors.Black,HsbColor.ToColor(channels[0].Value,channels[1].Value,100),0);ThemeService.Apply(this,SelectedColor,false);}
  void ShowColor(){if(!ThemeService.IsValid(hex.Text)){warning.Text="请输入 # 开头的六位色值，例如 #7C3AED。";return;}var color=(Color)ColorConverter.ConvertFromString(hex.Text);var hsb=HsbColor.FromColor(color);updating=true;try{if(hsb.S>0)channels[0].Value=hsb.H;channels[1].Value=hsb.S;channels[2].Value=hsb.B;}finally{updating=false;}RenderColor(color);}
  foreach(var color in new[]{"#16594D","#2563EB","#7C3AED","#BE185D","#C2410C","#334155"}){var button=new Button{Width=48,Height=32,Background=(Brush)new BrushConverter().ConvertFromString(color)!,ToolTip=color,Margin=new Thickness(0,0,8,0),Padding=new Thickness(0)};button.Click+=(_,_)=>hex.Text=color;swatches.Children.Add(button);}hex.TextChanged+=(_,_)=>{if(!updating)ShowColor();};foreach(var slider in channels)slider.ValueChanged+=(_,_)=>{if(updating)return;var color=HsbColor.ToColor(channels[0].Value,channels[1].Value,channels[2].Value);updating=true;try{hex.Text=$"#{color.R:X2}{color.G:X2}{color.B:X2}";}finally{updating=false;}RenderColor(color);};
  var actions=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,6,0,0)};panel.Children.Add(actions);var reset=new Button{Content="恢复默认",Margin=new Thickness(0,0,8,0)};reset.Click+=(_,_)=>hex.Text=ThemeService.DefaultColor;actions.Children.Add(reset);var save=new Button{Content="应用主题",IsDefault=true};save.SetResourceReference(StyleProperty,"PrimaryButton");save.Click+=(_,_)=>{if(ThemeService.IsValid(hex.Text))DialogResult=true;else ShowColor();};actions.Children.Add(save);ShowColor();
 }
}
